    var regionLabels = {
        page: 'Page Region', system: 'System Region', common: 'Common Region',
        designer: 'Designer Region', dynamic: 'Dynamic Region', menu: 'Menu',
        menu_sequence: 'Menu Sequence', login: 'Login', ad: 'Ad Region',
        cart: 'Cart', tag_cloud: 'Tag Cloud', mobile_switch: 'Mobile Switch', pdf: 'PDF',
        comments_block: 'Comments Block'
    };

    var regionIcons = {
        page: 'bi-window', system: 'bi-gear', common: 'bi-window-dock',
        designer: 'bi-palette', dynamic: 'bi-filetype-php', menu: 'bi-list',
        menu_sequence: 'bi-list-nested', login: 'bi-person', ad: 'bi-megaphone',
        cart: 'bi-cart', tag_cloud: 'bi-tags', mobile_switch: 'bi-phone', pdf: 'bi-file-pdf',
        comments_block: 'bi-chat-square-text'
    };

    // ── my_account pages cache ────────────────────────────────────────────
    // Populated by _fetchMyAccountDetailPages() (form_item_view pages used as
    // submission detail links from the my_account widget).
    var _myAccountDetailPagesCache = null;

    // ========================= COL CLASSES =========================
    function buildColClasses(p) {
        var c = [];
        if (p.xs && p.xs !== '' && p.xs !== 'none') {
            if (p.xs === 'auto') c.push('col-auto');
            else if (p.xs === 'col') c.push('col');
            else c.push('col-' + p.xs);
        } else if (!p.sm && !p.md && !p.lg && !p.xl && !p.xxl) c.push('col');
        ['sm','md','lg','xl','xxl'].forEach(function(bp) {
            if (p[bp] && p[bp] !== '' && p[bp] !== 'none')
                c.push(p[bp] === 'auto' ? 'col-' + bp + '-auto' : 'col-' + bp + '-' + p[bp]);
        });
        if (p.offsetXs && p.offsetXs !== '' && p.offsetXs !== 'none') c.push('offset-' + p.offsetXs);
        if (p.offsetMd && p.offsetMd !== '' && p.offsetMd !== 'none') c.push('offset-md-' + p.offsetMd);
        if (p.order && p.order !== '' && p.order !== 'default') c.push('order-' + p.order);
        if (p.cssClass) c.push(p.cssClass);
        return c.join(' ');
    }

    // ========================= ROW / COL CLASS PARSERS =========================
    // When a `semantic` div carries Bootstrap grid classes (row / col-*), we want
    // the designer to expose the same Row Options / Column Options panels as for
    // real row/col node types. These helpers parse the cssClass string into
    // structured props, and serialize props back into a class string after edits.
    //
    // Detection: any class equal to 'row' / 'col' / 'col-auto' / matching
    // /^col-(sm|md|lg|xl|xxl)?(-\d+|-auto)?$/ qualifies the div as row-like / col-like.
    function _hasRowClass(cssClass) {
        if (!cssClass) return false;
        return (' ' + cssClass + ' ').indexOf(' row ') !== -1;
    }
    function _hasColClass(cssClass) {
        if (!cssClass) return false;
        var parts = cssClass.split(/\s+/);
        for (var i = 0; i < parts.length; i++) {
            if (/^col(-(sm|md|lg|xl|xxl))?(-(\d{1,2}|auto))?$/.test(parts[i])) return true;
        }
        return false;
    }
    // Parse 'row g-3 justify-content-center align-items-end my-extra' into
    // { props: { gutter:'3', justify:'center', align:'end' }, rest: ['my-extra'] }.
    // 'row' itself is consumed (will be re-emitted by serializer).
    function _parseRowFromClasses(cssClass) {
        var classes = (cssClass || '').split(/\s+/).filter(Boolean);
        var props = { gutter: '', justify: '', align: '' };
        var rest = [];
        classes.forEach(function (c) {
            if (c === 'row') return;
            var m;
            if ((m = /^g-([0-5])$/.exec(c)))                                            { props.gutter  = m[1]; return; }
            if ((m = /^justify-content-(start|center|end|between|around|evenly)$/.exec(c))) { props.justify = m[1]; return; }
            if ((m = /^align-items-(start|center|end|stretch|baseline)$/.exec(c)))      { props.align   = m[1]; return; }
            rest.push(c);
        });
        return { props: props, rest: rest };
    }
    function _serializeRowToClasses(props, rest) {
        var cls = ['row'];
        if (props.gutter)  cls.push('g-' + props.gutter);
        if (props.justify) cls.push('justify-content-' + props.justify);
        if (props.align)   cls.push('align-items-' + props.align);
        // Preserve user's other classes
        (rest || []).forEach(function (c) { if (cls.indexOf(c) === -1) cls.push(c); });
        return cls.join(' ');
    }
    // Parse 'col-12 col-sm-8 offset-1 order-2 my-extra' into structured props.
    function _parseColFromClasses(cssClass) {
        var classes = (cssClass || '').split(/\s+/).filter(Boolean);
        var props = { xs: '', sm: '', md: '', lg: '', xl: '', xxl: '',
                       offsetXs: '', offsetMd: '', order: '' };
        var rest = [];
        classes.forEach(function (c) {
            var m;
            if (c === 'col')      { props.xs = 'col';  return; }
            if (c === 'col-auto') { props.xs = 'auto'; return; }
            if ((m = /^col-(\d{1,2})$/.exec(c)))                            { props.xs = m[1]; return; }
            if ((m = /^col-(sm|md|lg|xl|xxl)$/.exec(c)))                    { props[m[1]] = 'col';  return; }
            if ((m = /^col-(sm|md|lg|xl|xxl)-auto$/.exec(c)))               { props[m[1]] = 'auto'; return; }
            if ((m = /^col-(sm|md|lg|xl|xxl)-(\d{1,2})$/.exec(c)))          { props[m[1]] = m[2];   return; }
            if ((m = /^offset-(\d{1,2})$/.exec(c)))                         { props.offsetXs = m[1]; return; }
            if ((m = /^offset-md-(\d{1,2})$/.exec(c)))                      { props.offsetMd = m[1]; return; }
            if ((m = /^order-(first|last|\d+)$/.exec(c)))                   { props.order    = m[1]; return; }
            rest.push(c);
        });
        return { props: props, rest: rest };
    }
    function _serializeColToClasses(props, rest) {
        var cls = [];
        if (props.xs === 'col')        cls.push('col');
        else if (props.xs === 'auto')  cls.push('col-auto');
        else if (props.xs)             cls.push('col-' + props.xs);
        else if (!props.sm && !props.md && !props.lg && !props.xl && !props.xxl) cls.push('col');
        ['sm','md','lg','xl','xxl'].forEach(function (bp) {
            if (props[bp] === 'col')        cls.push('col-' + bp);
            else if (props[bp] === 'auto')  cls.push('col-' + bp + '-auto');
            else if (props[bp])             cls.push('col-' + bp + '-' + props[bp]);
        });
        if (props.offsetXs) cls.push('offset-' + props.offsetXs);
        if (props.offsetMd) cls.push('offset-md-' + props.offsetMd);
        if (props.order)    cls.push('order-' + props.order);
        (rest || []).forEach(function (c) { if (cls.indexOf(c) === -1) cls.push(c); });
        return cls.join(' ');
    }
    // After the user changes a Row Option on a semantic div, re-serialize the
    // edited props (which we stored on n.props temporarily for the panel) back
    // into n.props.cssClass, then clear them so subsequent reads stay in sync
    // with the cssClass (single source of truth for semantic nodes).
    function _rewriteCssClassFromRowProps(node) {
        if (!node || !node.props) return;
        var parsed = _parseRowFromClasses(node.props.cssClass || '');
        var merged = {
            gutter:  (node.props.gutter  != null ? node.props.gutter  : parsed.props.gutter)  || '',
            justify: (node.props.justify != null ? node.props.justify : parsed.props.justify) || '',
            align:   (node.props.align   != null ? node.props.align   : parsed.props.align)   || ''
        };
        node.props.cssClass = _serializeRowToClasses(merged, parsed.rest);
        // Don't keep transient gutter/justify/align on a semantic node — cssClass owns it.
        delete node.props.gutter; delete node.props.justify; delete node.props.align;
    }
    function _rewriteCssClassFromColProps(node) {
        if (!node || !node.props) return;
        var parsed = _parseColFromClasses(node.props.cssClass || '');
        var merged = {};
        ['xs','sm','md','lg','xl','xxl','offsetXs','offsetMd','order'].forEach(function (k) {
            merged[k] = (node.props[k] != null ? node.props[k] : parsed.props[k]) || '';
        });
        node.props.cssClass = _serializeColToClasses(merged, parsed.rest);
        ['xs','sm','md','lg','xl','xxl','offsetXs','offsetMd','order'].forEach(function (k) {
            delete node.props[k];
        });
    }
    // Hydrate a fresh copy of the node for the panel — fills in the parsed
    // row/col props on top of node.props so the existing propsRow()/propsCol()
    // builders can read them. The original node is unchanged; only a shallow
    // clone is used for the panel render. Edits flow through bindPropEvents
    // which re-serializes back to cssClass.
    function _hydrateSemanticRowProps(node) {
        var parsed = _parseRowFromClasses((node.props && node.props.cssClass) || '');
        node.props.gutter  = parsed.props.gutter;
        node.props.justify = parsed.props.justify;
        node.props.align   = parsed.props.align;
    }
    function _hydrateSemanticColProps(node) {
        var parsed = _parseColFromClasses((node.props && node.props.cssClass) || '');
        node.props.xs  = parsed.props.xs;
        node.props.sm  = parsed.props.sm;
        node.props.md  = parsed.props.md;
        node.props.lg  = parsed.props.lg;
        node.props.xl  = parsed.props.xl;
        node.props.xxl = parsed.props.xxl;
        node.props.offsetXs = parsed.props.offsetXs;
        node.props.offsetMd = parsed.props.offsetMd;
        node.props.order    = parsed.props.order;
    }

    // ========================= GOOGLE FONTS =========================
