        btn: {
            label: 'Button', icon: 'bi-hand-index',
            defaultProps: { text: 'Click Me', btnElement: 'a', href: '#', target: '', rel: '', btnType: 'button', variant: 'primary', size: '', outline: false, disabled: false, active: false, block: false },
            render: function (doc, p) {
                var elem = p.btnElement || 'a';
                var tag = (elem === 'button' || elem === 'input') ? elem : 'a';
                var el = doc.createElement(tag);
                var cls = 'btn btn-' + (p.outline ? 'outline-' : '') + (p.variant||'primary') + (p.size ? ' btn-' + p.size : '') + (p.block ? ' d-block w-100' : '') + (p.active ? ' active' : '') + (p.disabled ? ' disabled' : '');
                el.className = cls + (p.cssClass ? ' ' + p.cssClass : '');
                if (tag === 'a') {
                    el.href = p.href || '#';
                    if (p.target) el.target = p.target;
                    if (p.rel) el.rel = p.rel;
                    el.setAttribute('data-sd-ph', 'Button text');
                    if (p.text) el.textContent = p.text;
                } else if (tag === 'input') {
                    // <input type="button|submit|reset"> uses value, not text content
                    el.setAttribute('type', p.btnType || 'button');
                    el.value = p.text || '';
                } else {
                    // <button>
                    el.setAttribute('type', p.btnType || 'button');
                    el.setAttribute('data-sd-ph', 'Button text');
                    if (p.text) el.textContent = p.text;
                }
                return el;
            },
            toHTML: function (p, pad, children) {
                var elem = p.btnElement || 'a';
                var tag = (elem === 'button' || elem === 'input') ? elem : 'a';
                var cls = 'btn btn-' + (p.outline ? 'outline-' : '') + (p.variant||'primary') + (p.size ? ' btn-' + p.size : '') + (p.block ? ' d-block w-100' : '') + (p.active ? ' active' : '') + (p.disabled ? ' disabled' : '') + (p.cssClass ? ' ' + p.cssClass : '');
                var attrs = ' class="' + cls.trim() + '"';
                // textPosition controls canvas virtual-text side relative to children (icons).
                // 'end' (default) → children first then text (icon-left-of-label, the original order).
                // 'start'          → text first then children (icon-right-of-label).
                var kids = children || '';
                var tp = p.textPosition || 'end';
                var pre  = (tp === 'start') ? (p.text || '') : '';
                var post = (tp === 'start') ? '' : (p.text || '');
                if (tag === 'a') {
                    attrs = ' href="' + esc(p.href||'#') + '"' + (p.target ? ' target="' + esc(p.target) + '"' : '') + (p.rel ? ' rel="' + esc(p.rel) + '"' : '') + attrs;
                    if (kids) return pad + '<a' + attrs + '>' + pre + '\n' + kids + pad + post + '</a>\n';
                    return pad + '<a' + attrs + '>' + (p.text || '') + '</a>\n';
                } else if (tag === 'input') {
                    // <input> is void — cannot hold icon children; text goes in value
                    attrs = ' type="' + esc(p.btnType||'button') + '"' + ' value="' + esc(p.text||'') + '"' + attrs;
                    return pad + '<input' + attrs + '>\n';
                } else {
                    attrs = ' type="' + esc(p.btnType||'button') + '"' + attrs;
                    if (kids) return pad + '<button' + attrs + '>' + pre + '\n' + kids + pad + post + '</button>\n';
                    return pad + '<button' + attrs + '>' + (p.text || '') + '</button>\n';
                }
            }
        },
