            defaultProps: { tag: 'h2', text: 'Section Title', align: '', cssClass: '' },
            render: function (doc, p) {
                var el = doc.createElement(p.tag || 'h2');
                // Use innerHTML so rich text formatting (bold/italic etc.) is preserved.
                el.innerHTML = p.text !== undefined ? p.text : 'Section Title';
                // Legacy align prop: only add text-* if cssClass doesn't already have it.
                var _hcls = (p.cssClass || '').split(/\s+/);
                if (p.align && _hcls.indexOf('text-' + p.align) === -1) el.classList.add('text-' + p.align);
                if (p.cssClass) el.className += ' ' + p.cssClass;
                return el;
            },
            toHTML: function (p, pad) {
                var t = p.tag || 'h2';
                var _hclsArr = (p.cssClass || '').split(/\s+/);
                var alignStr = (p.align && _hclsArr.indexOf('text-' + p.align) === -1) ? 'text-' + p.align : '';
                var cls = alignStr + (p.cssClass ? ' ' + p.cssClass : '');
                // Output raw text — may contain rich text HTML; plain text is already safe here.
                return pad + '<' + t + (cls.trim() ? ' class="' + cls.trim() + '"' : '') + '>' + (p.text || '') + '</' + t + '>\n';
            }
