                    if (_had_protected && typeof sdToast === 'function') {
                        sdToast('Loop alanı silinemez — diğer seçili öğeler kaldırıldı.', 'warning');
                    }
                    saveState();
                    selectedNodes.filter(function(n) {
                        return n.type !== 'root'
                            && !n.props._locked
                            && !hasLockedAncestor(n)
                            && !_isDeleteProtected(n);
                    }).forEach(function(n) {
                        var p = findParent(n, tree);
                        if (p) p.children = p.children.filter(function(c) { return c !== n; });
                    });
