        // ── Phase 2: Sort control ─────────────────────────────────────────
        var sortEnEl = document.getElementById('sd-sw-sort-enabled');
        if (sortEnEl) {
            sortEnEl.addEventListener('change', function () {
                var sid = parseInt(this.dataset.swId, 10);
                if (!sid) return;
                var on = !!this.checked;
                _patchSysCfg(sid, function (cfg) {
                    cfg.sort_control_enabled = on;
                    // Initialise default selection on first enable so the
                    // dropdown isn't empty before the user picks any options.
                    if (on && (!Array.isArray(cfg.sort_options) || !cfg.sort_options.length)) {
                        cfg.sort_options = ['sort_order','name_asc','name_desc','price_asc','price_desc','newest'];
                    }
                }, { afterSave: function () { renderProperties(); } });
            });
        }
        // sort_options multi-toggle (each pill writes its key to/from the array)
        document.querySelectorAll('.sd-sw-sort-opt').forEach(function (el) {
            el.addEventListener('change', function () {
                var sid = parseInt(this.dataset.swId, 10);
                if (!sid) return;
                var picked = [];
                document.querySelectorAll('.sd-sw-sort-opt').forEach(function (t) {
                    if (t.checked && t.dataset.key) picked.push(t.dataset.key);
                });
                _patchSysCfg(sid, function (cfg) { cfg.sort_options = picked; });
            });
        });

        // ── Phase 2: Price filter ─────────────────────────────────────────
        var priceEnEl = document.getElementById('sd-sw-price-enabled');
