        // Catalog page picker — drives breadcrumb crumb URLs + cross-sell
        // card URLs. Numeric page_id stored in cfg. Selecting "0"
        // (Bağlanmasın) drops the key so the backend emits text crumbs.
        // We also clear any legacy catalog_listing_page_name (slug
        // string) on save so the two configs don't drift.
        var civCatPageEl = document.getElementById('sd-sw-civ-cat-page');
        if (civCatPageEl) {
            civCatPageEl.addEventListener('change', function () {
                var sid = parseInt(this.dataset.swId, 10);
                if (!sid) return;
                var pid = parseInt(this.value, 10);
                if (!(pid > 0)) pid = 0;
                _patchSysCfg(sid, function (cfg) {
                    if (pid > 0) cfg.catalog_listing_page_id = pid;
                    else if (cfg.catalog_listing_page_id !== undefined) delete cfg.catalog_listing_page_id;
                    // Drop legacy slug key — picker is the canonical source now.
                    if (cfg.catalog_listing_page_name !== undefined) delete cfg.catalog_listing_page_name;
                });
            });
        }
        // Variant attribute render style — widget-level default. When set
        // to anything other than 'select', the auto-injected variant
        // picker uses that style (radio / button_group / button_list).
        // Per-element variant_attr content types still control their own
        // style for fine-grained mixing.
        var civVarStyleEl = document.getElementById('sd-sw-civ-variant-style');
        if (civVarStyleEl) {
            civVarStyleEl.addEventListener('change', function () {
                var sid = parseInt(this.dataset.swId, 10);
                if (!sid) return;
                var v = ('' + this.value);
                _patchSysCfg(sid, function (cfg) { cfg.variant_render_style = v; });
            });
        }

        // Generic searchable-select wiring: any input with
        //   data-sd-search-target="<select-id>"
        // filters that <select>'s options as the user types. Bound at
        // document level (one-time) so it survives the property panel's
        // re-renders without leaking duplicate listeners. (Kept for any
        // legacy markup; new dropdowns prefer .sd-select2 below.)
        if (!document._sdSearchableInit) {
            document._sdSearchableInit = true;
            document.addEventListener('input', function (ev) {
                var t = ev.target;
                if (!t || !t.dataset || !t.dataset.sdSearchTarget) return;
                var sel = document.getElementById(t.dataset.sdSearchTarget);
                if (!sel) return;
                var q = ('' + (t.value || '')).toLowerCase();
                Array.prototype.forEach.call(sel.options, function (opt) {
                    // Never hide the placeholder/empty option (value 0 or '').
                    if (opt.value === '0' || opt.value === '') { opt.hidden = false; return; }
                    opt.hidden = q !== '' && opt.text.toLowerCase().indexOf(q) === -1;
                });
            });
        }

        // (Select2 init removed — clashed with the dark options-panel skin
        // and reset the selected value on each panel re-render. Search now
        // lives in the sibling input wired up by the data-sd-search-target
        // delegation above.)

