        // any other component. No system-cfg fields for it.)

        // ── EO: "Varsayılan Düzeni Yükle" button ──────────────────────────────
        // Atomically replaces the widget's tree with the default layout fetched
        // from /api.php?action=eo_default_tree. After the swap we re-walk the
        // tree to assign fresh _id values (the canvas uses them as map keys),
        // mark the shared component dirty, and re-render. The PHP renderer's
        // section-binding walker then takes over on next page view.
        var eoLoadDefEl = document.getElementById('sd-sw-eo-load-default');
        if (eoLoadDefEl) {
            eoLoadDefEl.addEventListener('click', function () {
                var sid = parseInt(this.dataset.swId, 10);
                if (!sid) return;
                if (!_sharedCache[sid]) {
                    sdToast('Widget önbellekte yok. Sayfayı yenileyip tekrar deneyin.', 'error');
                    return;
                }
                if (!window.confirm('Mevcut tasarım tamamen değiştirilecek ve geri alınamaz. Devam edilsin mi?')) return;

                var apiBase = (typeof path !== 'undefined' ? path : '') +
                              (typeof software_directory !== 'undefined' ? software_directory + '/' : '') + 'api.php';
                var token   = (typeof software_token !== 'undefined') ? software_token : '';
                var xhr = new XMLHttpRequest();
                xhr.open('POST', apiBase, true);
                xhr.setRequestHeader('Content-Type', 'application/json');
                xhr.onload = function () {
                    var resp;
                    try { resp = JSON.parse(xhr.responseText); } catch (e) { resp = null; }
                    if (!resp || resp.status !== 'success' || !resp.tree) {
                        sdToast('Varsayılan düzen yüklenemedi.', 'error');
                        return;
                    }
                    // Re-ID every node so the canvas doesn't end up with
                    // stale duplicates of pre-existing nodes' _id.
                    (function reId(nd) {
                        nd._id = (typeof gid === 'function') ? gid() : ('n' + Math.random().toString(36).slice(2, 10));
                        if (Array.isArray(nd.children)) nd.children.forEach(reId);
                    })(resp.tree);
                    if (typeof saveState === 'function') saveState();
                    _sharedCache[sid].tree = resp.tree;
                    _sharedDirty[sid] = true;
                    if (typeof render === 'function') render();
                    if (typeof renderProperties === 'function') renderProperties();
                    sdToast('Varsayılan düzen yüklendi.', 'success');
                };
                xhr.onerror = function () { sdToast('Ağ hatası.', 'error'); };
                xhr.send(JSON.stringify({ action: 'eo_default_tree', token: token }));
            });
        }

        // ── "Alıcı Listesi Bloku Ekle" handler — express_order only ───────────
        // Injects a single recipient_loop_area node into the widget root with a
        // useful starter template (heading + address grid). Designer rearranges
        // from there. Idempotent — if the tree already has a recipient_loop_area
        // the button is hidden by the props panel scan above, so this code path
        // never runs in that case.
        var eoAddRlaEl = document.getElementById('sd-sw-eo-add-recipient-loop');
        if (eoAddRlaEl) {
            eoAddRlaEl.addEventListener('click', function () {
                var sid = parseInt(this.dataset.swId, 10);
                if (!sid) return;
                var cache = _sharedCache[sid];
                if (!cache || !cache.tree) {
                    sdToast('Widget önbellekte yok. Sayfayı yenileyip tekrar deneyin.', 'error');
                    return;
                }
                if (typeof saveState === 'function') saveState();

                var _mkInput = function (eoField, type, placeholder, required) {
                    var attrs = [{ name: 'type', value: type || 'text' }, { name: 'value', value: '' }];
                    if (placeholder) attrs.push({ name: 'placeholder', value: placeholder });
                    if (required)    attrs.push({ name: 'required',    value: '' });
                    return createNode('semantic', {
                        tag: 'input', cssClass: 'form-control',
                        _attrs: attrs,
                        _bindings: { eo_field: eoField }
                    }, []);
                };
                var _mkLabel = function (forId, text, required) {
                    return createNode('semantic', {
                        tag: 'label', cssClass: 'form-label small fw-semibold',
                        text: required ? (text + ' *') : text,
                        _attrs: [{ name: 'for', value: forId }]
                    }, []);
                };
                var _mkField = function (col, label, eoField, type, ph, required) {
                    return createNode('semantic', { tag: 'div', cssClass: col }, [
                        _mkLabel(eoField, label, required),
                        _mkInput(eoField, type || 'text', ph || '', !!required)
                    ]);
                };

                var rlaNode = createNode('recipient_loop_area', {}, [
                    createNode('semantic', { tag: 'div', cssClass: 'pg-eo-recipient-block mb-3 p-3 border rounded' }, [
                        createNode('content', {
                            contentType: 'heading', tag: 'h3',
                            text: '^^__recipient_name^^',
                            cssClass: 'h6 text-muted mb-3',
                            _bindings: { text: '__recipient_name' }
                        }, []),
                        createNode('semantic', { tag: 'div', cssClass: 'row g-2' }, [
                            _mkField('col-12 col-md-6 mb-2', 'Ad',       'shipping_first_name', 'text', '', true),
                            _mkField('col-12 col-md-6 mb-2', 'Soyad',    'shipping_last_name',  'text', '', true),
                            _mkField('col-12 col-md-6 mb-2', 'Şirket',   'shipping_company',    'text', '', false),
                            _mkField('col-12 col-md-6 mb-2', 'Telefon',  'shipping_phone_number','tel', '', false),
                            _mkField('col-12 col-md-12 mb-2', 'Adres 1', 'shipping_address_1',  'text', '', true),
                            _mkField('col-12 col-md-12 mb-2', 'Adres 2', 'shipping_address_2',  'text', '', false),
                            _mkField('col-12 col-md-6 mb-2', 'Şehir',    'shipping_city',       'text', '', true),
                            _mkField('col-12 col-md-6 mb-2', 'Eyalet/İl','shipping_state',      'text', '', true),
                            _mkField('col-12 col-md-6 mb-2', 'Posta Kodu','shipping_zip_code',  'text', '', true),
                            createNode('semantic', { tag: 'div', cssClass: 'col-12 col-md-6 mb-2' }, [
                                _mkLabel('shipping_country', 'Ülke', true),
                                createNode('semantic', {
                                    tag: 'select', cssClass: 'form-select',
                                    _bindings: { eo_field: 'shipping_country' }
                                }, [])
                            ])
                        ])
                    ])
                ]);

                if (!cache.tree.children) cache.tree.children = [];
                cache.tree.children.push(rlaNode);
                _sharedDirty[sid] = true;

                if (typeof render === 'function') render();
                if (typeof renderProperties === 'function') renderProperties();
                sdToast('Alıcı Listesi bloku eklendi. Canvas üzerinde özelleştirebilirsiniz.', 'success');
            });
        }

        // NOTE: "Bölüm Bağlama (seçili öğeye)" dropdown handler removed —
        // the section-binding picker now lives on the per-element properties
        // panel (context-aware). Operators reported the widget-level
        // duplicate as confusing.

        // ── Universal "Varsayılan Düzeni Yükle" handler ───────────────────
        // Works for every system widget type that has a _buildStarterTree
        // entry (form_list_view, catalog_*, my_account, login_form,
        // forgot_password, search_results, registration, shopping_cart,
        // order_view, express_order, membership, custom_form, calendar_view).
        // Uses the LOCAL builder — no API round-trip needed since the
        // starter tree is fully constructed in JS.
        var loadDefEl = document.getElementById('sd-sw-load-default');
        if (loadDefEl) {
            loadDefEl.addEventListener('click', function () {
                var sid = parseInt(this.dataset.swId, 10);
                if (!sid) return;
                var rt = (this.getAttribute('data-region-type') || '').trim();
                if (!rt) { sdToast('Önce içerik türünü seçin.', 'warning'); return; }
                if (!_sharedCache[sid]) {
                    sdToast('Widget önbellekte yok. Sayfayı yenileyip tekrar deneyin.', 'error');
                    return;
                }
                if (typeof _buildStarterTree !== 'function') {
                    sdToast('Düzen şablonu üretici fonksiyon bulunamadı.', 'error');
                    return;
                }
                var newTree = _buildStarterTree(rt);
                if (!newTree) {
                    sdToast('Bu widget türü için varsayılan düzen tanımlı değil.', 'warning');
                    return;
                }
                if (!window.confirm('Mevcut canvas tasarımı tamamen değiştirilecek. Devam edilsin mi? (Ctrl+Z ile geri alabilirsiniz.)')) return;
                // Re-id every node so the canvas doesn\'t end up with stale
                // duplicates of pre-existing _id values.
                (function reId(nd) {
                    nd._id = (typeof gid === 'function') ? gid() : ('n' + Math.random().toString(36).slice(2, 10));
                    if (Array.isArray(nd.children)) nd.children.forEach(reId);
                })(newTree);
                if (typeof saveState === 'function') saveState();
                _sharedCache[sid].tree = newTree;
                _sharedDirty[sid] = true;
                if (typeof render === 'function') render();
                if (typeof renderProperties === 'function') renderProperties();
                sdToast('Varsayılan düzen yüklendi.', 'success');
            });
        }

