        // ── custom_form "Yeni Form Oluştur" button ────────────────────────────
        var cfNewFormBtn = document.getElementById('sd-cf-new-form-btn');
        if (cfNewFormBtn) {
            cfNewFormBtn.addEventListener('click', function () {
                window.open('add_page.php?preset_type=custom+form', '_blank');
            });
        }

        // ── custom_form "Alanları Yerleştir / Sıfırla" button ─────────────────
        var cfInjectBtn = document.getElementById('sd-cf-inject-btn');
        if (cfInjectBtn) {
            cfInjectBtn.addEventListener('click', function () {
                var _ciSid = parseInt(this.dataset.swId, 10);
                if (!_ciSid) return;
                var _ciCached = _sharedCache[_ciSid];
                if (!_ciCached) return;
                var _ciCfg = {};
                try { _ciCfg = _ciCached.system_region_config ? JSON.parse(_ciCached.system_region_config) : {}; } catch (e) {}
                if (_ciCfg._form_injected) {
                    // Reset mode: remove injected fields, restore placeholder
                    _cfResetFields(_ciSid);
                } else {
                    // Inject mode: fetch fields then inject
                    var _ciFormId = parseInt(_ciCfg.form_id || _ciCfg.custom_form_page_id || 0, 10);
                    if (!_ciFormId) return;
                    _fetchFormFields(_ciFormId, function (fields) {
                        if (!fields || fields.length === 0) {
                            sdToast('Bu formda alan bulunamadı.', 'info');
                            return;
                        }
                        _cfInjectFields(_ciSid, fields);
                    });
                }
            });
        }

        // ── calendar_view settings ────────────────────────────────────────────

        // events_limit (number, empty = unlimited)
        var cvEventsLimitEl = document.getElementById('sd-sw-cv-events-limit');
        if (cvEventsLimitEl) {
            cvEventsLimitEl.addEventListener('change', function () {
                var sid = parseInt(this.dataset.swId, 10);
                if (!sid) return;
                var raw = ('' + this.value).trim();
                var v = raw === '' ? 0 : parseInt(raw, 10);
                if (!(v > 0)) v = 0;
                this.value = v > 0 ? v : '';
                _patchSysCfg(sid, function (cfg) { cfg.events_limit = v; });
            });
        }

        // date_format (select)
        var cvDateFmtEl = document.getElementById('sd-sw-cv-date-format');
