                        '<button type="button" class="sd-theme-mode-tab" data-theme-mode="dark"><span class="bi bi-moon me-1"></span>Dark</button>' +
                    '</div>' +
                    '<div id="sd-theme-vars"></div>' +
                '</div>' +
            '</div>';
        rightPanel.appendChild(wrap);

        // ── CodeMirror modal ──────────────────────────────────────────────────
        var modalEl = document.createElement('div');
