        // ── Parse all Bootstrap icons from loaded stylesheets ──
        // Falls back to an empty list (the grid just stays empty) if no sheets are accessible.
        function parseBootstrapIcons() {
            var result = [], seen = {};
            try {
                var sheets = document.styleSheets;
                for (var i = 0; i < sheets.length; i++) {
                    var rules;
                    try { rules = sheets[i].cssRules || sheets[i].rules; }
                    catch (e) { continue; }
                    if (!rules) continue;
                    for (var j = 0; j < rules.length; j++) {
                        var sel = rules[j].selectorText;
                        if (!sel) continue;
                        // Match .bi-icon-name::before  (both :: and : variants)
                        var m = sel.match(/\.(bi-[\w-]+):+before/);
                        if (m && !seen[m[1]]) {
                            seen[m[1]] = true;
                            result.push(m[1]);
                        }
                    }
                }
            } catch (e) {}
            return result.sort();
        }

